    "description": "新华社华盛顿9月14日电（记者黄强 徐剑梅）美军中央司令部14日在社交媒体发文否认一艘悬挂巴拿马国旗的油轮近期在霍尔木兹海峡触碰水雷。 美军中央司令部称，伊朗伊斯兰革命卫队此前相关说法不符合事实。这艘油轮上个月就遭伊朗导弹袭击而丧失航行能力，伊朗上周末使用无人机对停泊在阿曼沿海水域的该油轮再次发动袭击。目前，该油轮正由美方的地区伙伴拖曳。 据伊朗法尔斯通讯社14日早些时候报道，伊朗伊斯兰革命卫队方面表示，一艘名为“阿尔加亚”的油轮试图通…",
    "content": "新华社华盛顿9月14日电（记者黄强 徐剑梅）美军中央司令部14日在社交媒体发文否认一艘悬挂巴拿马国旗的油轮近期在霍尔木兹海峡触碰水雷。 美军中央司令部称，伊朗伊斯兰革命卫队此前相关说法不符合事实。这艘油轮上个月就遭伊朗导弹袭击而丧失航行能力，伊朗上周末使用无人机对停泊在阿曼沿海水域的该油轮再次发动袭击。目前，该油轮正由美方的地区伙伴拖曳。 据伊朗法尔斯通讯社14日早些时候报道，伊朗伊斯兰革命卫队方面表示，一艘名为“阿尔加亚”的油轮试图通过霍尔木兹海峡南部“禁航区域”时，触碰水雷后爆炸起火。"
