    "author": "澎湃新闻记者 谢煜楠 编辑 唐燕丽 素材来源 相关人士",
    "description": "澎湃新闻湖南长沙读者彭程反映，2015年，“织机街56号”在未获审批的情况下建设饭店，施工方与他家“织机街54号”共用墙体和天花板，施工过程中把承重墙改为楼梯，导致他家变成危房。饭店经营者称，当年是56号业主和彭程父亲约定一起共用墙体往上加建。长沙市自规局相关负责人表示，针对饭店涉嫌未批先建情况，城管部门已立案处置。",
    "content": "澎湃新闻湖南长沙读者彭程反映，2015年，“织机街56号”在未获审批的情况下建设饭店，施工方与他家“织机街54号”共用墙体和天花板，施工过程中把承重墙改为楼梯，导致他家变成危房。饭店经营者称，当年是56号业主和彭程父亲约定一起共用墙体往上加建。长沙市自规局相关负责人表示，针对饭店涉嫌未批先建情况，城管部门已立案处置。"
