    "author": "欧七斤（上海交通大学）",
    "description": "大学是社会的灯塔，其既以“天下为己任”，更以“真理为依归”。澎湃新闻·私家历史联合大学史研究者张淑锵，特别推出“大学堂”系列，回望中国晚清民国高等教育的起源与大学师者的风骨，重温那些关于求是、存真、独立、自由与担当的大学精神与人文传统。不仅重述校史，更要追问：大学为何而立，知识为何而求，教育又应当培养怎样的人。 盛宣怀（1844-1916），字杏荪，别署愚斋，晚号止叟。江苏常州人，是清末洋务运动的重要代表人物，也是中国近代著名的政治家、…",
    "content": "大学是社会的灯塔，其既以“天下为己任”，更以“真理为依归”。澎湃新闻·私家历史联合大学史研究者张淑锵，特别推出“大学堂”系列，回望中国晚清民国高等教育的起源与大学师者的风骨，重温那些关于求是、存真、独立、自由与担当的大学精神与人文传统。不仅重述校史，更要追问：大学为何而立，知识为何而求，教育又应当培养怎样的人。 盛宣怀（1844-1916），字杏荪，别署愚斋，晚号止叟。江苏常州人，是清末洋务运动的重要代表人物，也是中国近代著名的政治家、实业家、教育家与慈善家。他早年投身李鸿章幕府，深受器重，毕生以兴办洋务实业为志业…"
