    "description": "1937年9月，27岁的文坛新星李长之从北方辗转至昆明。次年5月，他基于在昆生活杂感，于广州杂志《宇宙风》上发表《昆明杂记》一文，描摹全面抗战初期云南人文风貌。因其中将昆明人隐喻为“牛”，又将云南略显慵懒、不讲求办事效率的“慢节奏”生活一一写入文中，遂招致本地人士不满，后方文坛为之震荡。在各方压力下，李长之被“驱逐”出云南，此即抗战文学史上著名的“李长之被逐”事件。 之后风雨如晦的人生中，一代文坛巨匠对此大多缄默不言，应有往事沧桑，“忍…",
    "content": "1937年9月，27岁的文坛新星李长之从北方辗转至昆明。次年5月，他基于在昆生活杂感，于广州杂志《宇宙风》上发表《昆明杂记》一文，描摹全面抗战初期云南人文风貌。因其中将昆明人隐喻为“牛”，又将云南略显慵懒、不讲求办事效率的“慢节奏”生活一一写入文中，遂招致本地人士不满，后方文坛为之震荡。在各方压力下，李长之被“驱逐”出云南，此即抗战文学史上著名的“李长之被逐”事件。 之后风雨如晦的人生中，一代文坛巨匠对此大多缄默不言，应有往事沧桑，“忍堪回首”之意味。他只在1948年《杂忆佩弦先生》 （《文讯》[北平]，1948年…"
