    "content": "9月12日，由20多名印尼农村基层干部及相关工作人员组成的研修班到云南西双版纳开展实地考察，详细了解当地特色产业培育、乡村振兴、惠农富民等方面的发展成效与实践经验。 其间，研修班走进景洪市普文镇的一家咖啡庄园，详细了解咖啡产业标准化种植、精深加工、市场销售全链条发展模式，深入汲取当地依托全产业链布局，推动咖啡产业发展、助力乡村产业升级的成熟经验。在普文镇水产养殖基地，研修班实地考察生态标准化养殖，特色食品深加工，低值渔获资源化循环利用的发展路径。 研修班学员深入勐罕镇“三曼”村，重点考察学习边疆民族村寨融合发展与乡…"
