    "content": "新华社基辅9月14日电（记者李东旭）乌克兰总统泽连斯基14日说，若美方能确保俄方就停止战争作出“真正和长期”的承诺，乌方愿推动局势降温。但他同时说，目前并无迹象表明俄方有真正的止战意愿。 泽连斯基当晚在视频讲话中说，美方强烈建议俄乌停止针对关键基础设施的互袭，若这一建议成为推动局势降温的第一步，乌方愿意予以支持。他同时称，虽然乌方对俄“战时经济”的打击让俄方承压，但目前没有迹象表明俄方真正想要止战。 泽连斯基说，俄乌停止互袭的磋商必须涵盖能源、粮食运输通道、关键基础设施等事宜。他还说，乌方所需方案“不应仅仅是为了迎…"
