    "content": "新华社纽约9月14日电 纽约股市三大股指14日下跌。 截至当天收盘，道琼斯工业平均指数比前一交易日下跌152.09点，收于52421.2点，跌幅为0.29%；标准普尔500种股票指数下跌37点，收于7619.98点，跌幅为0.48%；纳斯达克综合指数下跌146.62点，收于26186.41点，跌幅为0.56%。 板块方面，标普500指数十一大板块八跌三涨。科技板块和工业板块分别以1.67%和1.44%的跌幅领跌，通信服务板块和医疗板块分别以2.79%和1.35%的涨幅领涨。"
