    "author": "张玉亮,朱昊晨",
    "description": "9月14日，在芬兰北部城市罗瓦涅米，丹麦首相弗雷泽里克森参加欧洲北极峰会结束后的新闻发布会。新华社发（芬兰总理办公室供图） 新华社芬兰罗瓦涅米9月14日电（记者张玉亮）丹麦首相弗雷泽里克森14日在芬兰北部城市罗瓦涅米表示，希望丹麦与美国在北极和格陵兰岛问题上通过合作找到解决方案。 弗雷泽里克森当天在欧洲北极峰会结束后的新闻发布会上说，丹麦与美国有关格陵兰岛问题的高级别工作组仍在开展工作，虽然尚不能作出结论，但她对找到解决方案持乐观态度。…",
    "content": "9月14日，在芬兰北部城市罗瓦涅米，丹麦首相弗雷泽里克森参加欧洲北极峰会结束后的新闻发布会。新华社发（芬兰总理办公室供图） 新华社芬兰罗瓦涅米9月14日电（记者张玉亮）丹麦首相弗雷泽里克森14日在芬兰北部城市罗瓦涅米表示，希望丹麦与美国在北极和格陵兰岛问题上通过合作找到解决方案。 弗雷泽里克森当天在欧洲北极峰会结束后的新闻发布会上说，丹麦与美国有关格陵兰岛问题的高级别工作组仍在开展工作，虽然尚不能作出结论，但她对找到解决方案持乐观态度。 谈及北极安全合作，弗雷泽里克森说，目前多个盟国在格陵兰岛开展联合演习，欧洲及跨…"
