    "description": "新华社莫斯科9月14日电 俄罗斯国防部14日在社交媒体发布通报称，俄军过去24小时内在哈尔科夫、顿涅茨克和扎波罗热方向持续推进，新控制3处居民点。 通报还称，俄军战术航空兵、攻击型无人机、导弹部队和炮兵对乌克兰142个地区的后勤中心、能源和交通基础设施、无人机组装车间和仓库等目标进行打击。此外，俄黑海舰队在克里米亚附近海域摧毁一艘乌军无人艇。 乌方对此暂未作出回应。",
    "content": "新华社莫斯科9月14日电 俄罗斯国防部14日在社交媒体发布通报称，俄军过去24小时内在哈尔科夫、顿涅茨克和扎波罗热方向持续推进，新控制3处居民点。 通报还称，俄军战术航空兵、攻击型无人机、导弹部队和炮兵对乌克兰142个地区的后勤中心、能源和交通基础设施、无人机组装车间和仓库等目标进行打击。此外，俄黑海舰队在克里米亚附近海域摧毁一艘乌军无人艇。 乌方对此暂未作出回应。"
