    "content": "新华社日本名古屋9月14日电 14日，爱知·名古屋亚运会女足项目正式开赛。小组赛首轮比赛中，中国女足凭借王霜的两粒进球和两次助攻，以5:1大胜中国香港队，取得本届亚运会“开门红”。 9月14日，中国队球员王霜（左）在比赛中射门，打入个人本场比赛第二粒进球。新华社记者 贾浩成 摄 比赛伊始，实力明显占据优势的中国队就对中国香港队形成全面压制。第14分钟，王霜巧妙做球，陈巧珠禁区外远射破门，为中国队打破僵局。然而第31分钟，中国队后卫司雨和门将肖梓彤连续出现低级失误，送给中国香港队空门机会，张炜琪将比分扳平。七分钟后，…"
