    "content": "国际原子能机构14日发布《能源、电力与核电估算2060》展望报告显示，到2060年，全球核电装机容量可能增长两倍以上。这是该机构连续第六年上调其对核电扩张的预测。 新华社维也纳9月14日电（记者刘海燕 孟凡宇）国际原子能机构14日发布《能源、电力与核电估算2060》展望报告显示，到2060年，全球核电装机容量可能增长两倍以上。这是该机构连续第六年上调其对核电扩张的预测。 国际原子能机构在第70届大会开幕当天发布这份展望报告。报告说，随着各国越来越多地考虑利用核电来满足电力需求、保障能源安全，到2060年全球核电装机…"
