    "author": "张玉洁,戴斌",
    "description": "这是9月14日拍摄的湖南大学非洲研究院马达加斯加研究中心揭牌仪式现场。新华社记者 戴斌 摄 新华社长沙9月14日电（记者张玉洁、戴斌）马达加斯加总理拉乔纳里松·马米蒂亚纳14日为湖南大学非洲研究院马达加斯加研究中心揭牌。该中心成立将为深化中马全面战略合作伙伴关系、助力湘马经贸高质量合作搭建起集智库研究、产业赋能、人文交流于一体的学术平台。 据介绍，中心由湖南大学非洲研究院设立，汇聚多学科研究力量，研究重点涵盖马达加斯加营商环境、中马产业…",
    "content": "这是9月14日拍摄的湖南大学非洲研究院马达加斯加研究中心揭牌仪式现场。新华社记者 戴斌 摄 新华社长沙9月14日电（记者张玉洁、戴斌）马达加斯加总理拉乔纳里松·马米蒂亚纳14日为湖南大学非洲研究院马达加斯加研究中心揭牌。该中心成立将为深化中马全面战略合作伙伴关系、助力湘马经贸高质量合作搭建起集智库研究、产业赋能、人文交流于一体的学术平台。 据介绍，中心由湖南大学非洲研究院设立，汇聚多学科研究力量，研究重点涵盖马达加斯加营商环境、中马产业链供应链合作、粮食安全与农业技术协作、人文交流与民心相通等方向，助力推动中马合作…"
