    "description": "中新社杭州9月14日电 (郭其钰)中国经济社会理事会和欧盟经济社会委员会第二十一次圆桌会议14日在浙江杭州召开。中欧代表围绕“解决贫困问题，促进社会包容”“推动中欧贸易投资提质增效”“以人为本的人工智能”等议题深入交流，共话中欧合作新机遇。",
    "content": "中新社杭州9月14日电 (郭其钰)中国经济社会理事会和欧盟经济社会委员会第二十一次圆桌会议14日在浙江杭州召开。中欧代表围绕“解决贫困问题，促进社会包容”“推动中欧贸易投资提质增效”“以人为本的人工智能”等议题深入交流，共话中欧合作新机遇。"
