    "title": "校馆弦歌丨中央民族大学图书馆 典籍里的团结密码",
    "link": "http://www.news.cn/20260914/eabf96ba870c4a84ae0379af3e66d8ab/c.html",
    "pub_date": "2026-09-14 21:54:46",
    "author": "潘禹杰,马晓冬",
    "description": "中央民族大学图书馆始建于1951年，是全国民族团结进步教育基地、全国古籍重点保护单位。现有海淀校区和丰台校区两个馆舍，共拥有纸质文献224万余册（件），其中包括古籍22万余册，民族学科文献和古籍文献资料收藏独具优势，馆藏有多文种的民族文字图书及线装古籍、旧平装图书等。 记者：潘禹杰、马晓冬 新华社音视频部制作",
    "content": "中央民族大学图书馆始建于1951年，是全国民族团结进步教育基地、全国古籍重点保护单位。现有海淀校区和丰台校区两个馆舍，共拥有纸质文献224万余册（件），其中包括古籍22万余册，民族学科文献和古籍文献资料收藏独具优势，馆藏有多文种的民族文字图书及线装古籍、旧平装图书等。 记者：潘禹杰、马晓冬 新华社音视频部制作"
