    "pub_date": "2026-09-14 21:48:09",
    "author": "涂洪长,林凯,秦宏",
    "description": "新华社福州9月14日电 题：风展红旗物华新——福建长征出发地的故事与新章 新华社记者涂洪长、林凯、秦宏 福建，一片革命热土，10多万儿女参加红军，近3万人踏上长征。福建长汀、宁化是中央红军长征的重要出发地，1934年，部分红军将士从这里踏上伟大远征。 90余载过去，福建老区苏区迎来沧桑巨变，而红色信仰与奋斗精神却历久弥新。 2021年3月，习近平总书记在福建考察时强调：“要推进老区苏区全面振兴，倾力支持老区苏区特色产业提升、基础设施建设…",
    "content": "新华社福州9月14日电 题：风展红旗物华新——福建长征出发地的故事与新章 新华社记者涂洪长、林凯、秦宏 福建，一片革命热土，10多万儿女参加红军，近3万人踏上长征。福建长汀、宁化是中央红军长征的重要出发地，1934年，部分红军将士从这里踏上伟大远征。 90余载过去，福建老区苏区迎来沧桑巨变，而红色信仰与奋斗精神却历久弥新。 2021年3月，习近平总书记在福建考察时强调：“要推进老区苏区全面振兴，倾力支持老区苏区特色产业提升、基础设施建设和公共服务保障等。” 乘着新时代的东风，长征精神洗礼过的八闽红土地，如今到处是催…"
