    "content": "新华社杭州9月14日电（记者段菁菁）中国经济社会理事会和欧盟经济社会委员会第二十一次圆桌会议14日在杭州召开。37位中欧代表围绕“解决贫困问题，促进社会包容”“推动中欧贸易投资提质增效”和“以人为本的人工智能”深入交流。全国政协副主席兼秘书长、中国经济社会理事会主席王东峰出席并讲话。 王东峰表示，在中欧建交50周年的重要节点时间，习近平主席会见欧洲理事会主席科斯塔和欧盟委员会主席冯德莱恩，就中欧关系发展深入交换意见，达成重要共识，为新形势下中欧关系发展指明了方向。中欧双方要坚持伙伴定位，坚持开放包容，坚持多边主义，…"
