    "content": "新华社北京9月14日电 据中国羽毛球协会14日消息，2026年爱知·名古屋亚运会中国体育代表团羽毛球项目男子双打运动员陈柏阳因突发疾病无法参赛，将由何济霆替补。 9月1日，陈柏阳（左）与刘毅在2026中国羽毛球大师赛男子双打首轮比赛中。新华社发（彭志刚摄） 据悉，陈柏阳近期突发疾病引发身体不适，经国家羽毛球队队医和多家医院专家会诊，确定其身体状态无法参加亚运会比赛。目前，陈柏阳病情已经得到很好的控制，身体正在恢复当中，还需要静养2周到4周。 按照原参赛阵容，陈柏阳与刘毅作为双打搭档参加亚运会羽毛球项目男子团体和男子…"
