    "description": "9月14日，在奥地利维也纳，伊朗驻国际原子能机构代表礼萨·纳杰菲在国际原子能机构第70届大会上发言。新华社记者 贺灿铃 摄 新华社德黑兰/维也纳9月14日电（记者孟凡宇 刘海燕）伊朗伊斯兰共和国广播电视台14日报道说，伊朗原子能组织主席伊斯拉米12日搭乘航班前往奥地利参加国际原子能机构第70届大会，但因受到美国等方面阻挠，12日当天返回伊朗首都德黑兰。伊朗驻国际原子能机构代表14日在大会上谴责此举侵犯其成员国权利。 伊朗外交部发言人巴加…",
    "content": "9月14日，在奥地利维也纳，伊朗驻国际原子能机构代表礼萨·纳杰菲在国际原子能机构第70届大会上发言。新华社记者 贺灿铃 摄 新华社德黑兰/维也纳9月14日电（记者孟凡宇 刘海燕）伊朗伊斯兰共和国广播电视台14日报道说，伊朗原子能组织主席伊斯拉米12日搭乘航班前往奥地利参加国际原子能机构第70届大会，但因受到美国等方面阻挠，12日当天返回伊朗首都德黑兰。伊朗驻国际原子能机构代表14日在大会上谴责此举侵犯其成员国权利。 伊朗外交部发言人巴加埃当天在新闻发布会上说，奥地利未给伊朗代表团签发入境签证，奥地利政府向伊朗表示此…"
