    "content": "新华社长春9月14日电（记者周万鹏、李典）14日，2027年第33届世界大学生冬季运动会代表团团长会议在长春启幕。国际大学生体育联合会主席雷诺·艾德在此间接受新华社记者采访时表示，目前赛事各项筹备工作进展顺利，期待本届大冬会参赛代表团数量创下新纪录。 本次团长会议设置场馆考察、答疑交流、城市风貌体验等环节。会议期间，各国家和地区代表团团长将实地考察场馆设施与服务保障情况，感受“北国春城”的冰雪魅力。 “每次回到长春都让人心情愉悦。”艾德说，“这里的人们热情好客，美食也很棒，大家都非常友善，期待本届赛事参赛代表团数量…"
