    "description": "新华社北京9月14日电 韩国媒体14日发布的一项民意调查结果显示，总统李在明的支持率降至33.8%，为其去年6月上任以来新低。韩国国务总理韩圣淑表示，政府正在认真倾听民意，反思不足并加以改进。 韩国民调机构“真实计量器”7日至11日就李在明施政情况对全国2515名成年人展开调查。民调结果显示，李在明支持率为33.8%，较一周前下降3.6个百分点，连续9周下滑；不支持率为63.3%，较一周前上升3.8个百分点。 8月15日，在韩国首尔世宗…",
    "content": "新华社北京9月14日电 韩国媒体14日发布的一项民意调查结果显示，总统李在明的支持率降至33.8%，为其去年6月上任以来新低。韩国国务总理韩圣淑表示，政府正在认真倾听民意，反思不足并加以改进。 韩国民调机构“真实计量器”7日至11日就李在明施政情况对全国2515名成年人展开调查。民调结果显示，李在明支持率为33.8%，较一周前下降3.6个百分点，连续9周下滑；不支持率为63.3%，较一周前上升3.8个百分点。 8月15日，在韩国首尔世宗文化会馆，韩国总统李在明发表致辞。新华社/纽西斯通讯社 “真实计量器”认为，李在…"
