    "content": "新华社呼和浩特9月14日电（记者陈玉麒）9月的内蒙古额尔古纳市恩和俄罗斯族民族乡（以下简称恩和乡），天还没完全亮透，就有人支起了画架。晨雾里，来自内蒙古艺术学院的学生三三两两走进小镇，开展为期20天的写生实践。 据恩和俄罗斯族民族乡党委委员、宣传委员曹亚楠介绍，2017年谋划打造油画小镇之前，当地旅游主要依托木刻楞民居和俄罗斯族民俗吸引过路游客，存在游客停留时间短、淡旺季悬殊等短板。康养、露营、民俗演艺等业态都曾纳入考量，最终选定油画方向，看中的是“差异化、不可复制”。 恩和乡的底气，来自它本就“入画”。内蒙古艺术…"
