    "content": "新华社澳门9月14日电（记者宋晨、齐菲）记者14日获悉，第十九届澳门妈祖文化旅游节将于10月12日至15日在澳门举办，活动立足“文化搭台、经贸唱戏”初衷，依托澳门“一中心、一平台、一基地”优势，将进一步深化文旅经贸合作，促进两岸及海内外人文交流。 活动组委会主席陈明金介绍，妈祖信俗于2009年被联合国教科文组织列入人类非物质文化遗产代表作名录，内涵持续丰富。今年我国宣布将推动气象智能预警方案“妈祖”在30个国家落地应用，实现传统妈祖人文精神与现代科技相融合，诠释济世安民、守望相助的初心。 他表示，本届活动闽澳联动亮…"
