    "description": "新华社福州9月14日电（记者姜克红）日前，福建省林业局组织福建农林大学、厦门大学等专家团队，深入福建建瓯万木林省级自然保护区开展第三次全国古树名木资源普查。通过无人机激光雷达和人工攀树等方式精确测量，发现一株51.5米高的枫香古树，这是福建省有记录的最高树，也是全省唯一一株树高超过50米的古树，其胸围332厘米，树龄190年，主干通直、树形挺拔、枝叶繁茂。 调查队员为万木林枫香古树测量树围。新华社发（黄海 摄） 建瓯万木林是由人工杉木林…",
    "content": "新华社福州9月14日电（记者姜克红）日前，福建省林业局组织福建农林大学、厦门大学等专家团队，深入福建建瓯万木林省级自然保护区开展第三次全国古树名木资源普查。通过无人机激光雷达和人工攀树等方式精确测量，发现一株51.5米高的枫香古树，这是福建省有记录的最高树，也是全省唯一一株树高超过50米的古树，其胸围332厘米，树龄190年，主干通直、树形挺拔、枝叶繁茂。 调查队员为万木林枫香古树测量树围。新华社发（黄海 摄） 建瓯万木林是由人工杉木林历经670余年自然演替形成的中亚热带常绿阔叶林。1957年，万木林被列入全国首批…"
