    "content": "新华社福州9月14日电 题：松毛岭战役：长征前在福建的最后血战 新华社记者李昊泽 在福建省长汀县南山镇，苍松掩映间，松毛岭战斗烈士纪念碑巍然矗立。不远处的战斗旧址中，残存的战壕顺着山脊蜿蜒铺开，无声讲述着当年那场血战的壮烈。 时间拨回到1934年，横亘于长汀东南部的松毛岭，以其险要山势成为拱卫中央苏区政治与经济中心的天然屏障，为阻止敌人西进攻占瑞金、长汀，松毛岭战役就此打响。 在松毛岭上，驻守阵地的红九军团等部队的红军将士，进行了一场惨烈的战斗：装备精良的国民党军在飞机重炮掩护下轮番猛攻阵地，红军将士依托山地工事浴…"
