    "description": "新华社巴黎9月14日电（记者孙毅）法国总统府爱丽舍宫14日发表声明说，芬兰当天决定加入法国总统马克龙提出的“前沿威慑”计划。 声明说，芬兰决定加入法国“前沿威慑”计划，两国将在未来几个月内成立一个核事务指导小组，启动相关合作。 芬兰总统斯图布当天在社交媒体发文说，法国这项计划不会取代或与北约的核威慑重叠。他还说，芬兰无意在和平时期在其领土部署核武器。 3月2日，马克龙在法国西部长岛军事基地就法国的核威慑政策发表讲话，称未来法国不仅要增加…",
    "content": "新华社巴黎9月14日电（记者孙毅）法国总统府爱丽舍宫14日发表声明说，芬兰当天决定加入法国总统马克龙提出的“前沿威慑”计划。 声明说，芬兰决定加入法国“前沿威慑”计划，两国将在未来几个月内成立一个核事务指导小组，启动相关合作。 芬兰总统斯图布当天在社交媒体发文说，法国这项计划不会取代或与北约的核威慑重叠。他还说，芬兰无意在和平时期在其领土部署核武器。 3月2日，马克龙在法国西部长岛军事基地就法国的核威慑政策发表讲话，称未来法国不仅要增加核弹头数量，还要和欧洲其他国家执行“前沿威慑”计划。他宣布已有德国、英国、波兰、…"
