    "content": "新华社日本名古屋9月14日电（记者岳晨星）爱知·名古屋亚运会男篮小组赛14日在爱知国际体育馆继续进行。中国队以105:61大胜卫冕冠军菲律宾队，以三战全胜的战绩位列C组第一，晋级八强。 9月14日，中国队球员王俊杰（中）在比赛中上篮。新华社记者 王东震 摄 三年前的杭州亚运会男篮半决赛，中国队以76:77一分之差惜败于菲律宾队，后者最终夺冠。 此役中国队开场后迅速进入状态，以7:0先声夺人。首节后半段，胡明轩连续命中三记三分球，帮助球队进一步拉开分差。中国队以36:16领先结束首节。 次节，中国队延续高强度防守战术…"
