    "description": "新华社北京9月14日电（记者王春涛）“任何助长日本军事野心的举动，只会把地区推向危险的漩涡，也必将祸及自身。”国防部新闻发言人蒋斌14日表示。 针对有关日本陆上自卫队与美国、澳大利亚两国陆军在日本举行“东方之盾26”联合演习的提问，蒋斌表示，演习以“盾”为名做包装，实则是推进战略进攻性武器前沿部署，损害他国正常安全利益，推高地区军备竞赛和军事对抗风险，严重威胁地区安全稳定，我们对此坚决反对。 蒋斌说，近年来，日本不断突破和平宪法和“专守…",
    "content": "新华社北京9月14日电（记者王春涛）“任何助长日本军事野心的举动，只会把地区推向危险的漩涡，也必将祸及自身。”国防部新闻发言人蒋斌14日表示。 针对有关日本陆上自卫队与美国、澳大利亚两国陆军在日本举行“东方之盾26”联合演习的提问，蒋斌表示，演习以“盾”为名做包装，实则是推进战略进攻性武器前沿部署，损害他国正常安全利益，推高地区军备竞赛和军事对抗风险，严重威胁地区安全稳定，我们对此坚决反对。 蒋斌说，近年来，日本不断突破和平宪法和“专守防卫”原则，大力发展远程进攻性武器，借对外军演加速推进“再军事化”，谋求军事扩张…"
