    "content": "新华社北京9月14日电 国际乒联14日公布最新一期世界排名，中国选手王曼昱超越队友孙颖莎，首次登顶女单世界第一。 在现行世界排名体系下，运动员的世界排名积分由过去12个月内取得的八站最高积分之和组成。由于孙颖莎和王曼昱均缺席2026年世界乒乓球职业大联盟（WTT）澳门冠军赛，身为去年赛事冠军的孙颖莎被扣除1000点世界排名积分，去年亚军王曼昱被扣除700点世界排名积分，导致两人位次发生变化，目前王曼昱的世界排名积分比孙颖莎高出140分。 女单排名第三至第十的运动员分别是张本美和（日本）、蒯曼（中国）、王艺迪（中国）…"
