    "content": "新华社北京9月14日电（记者吴梦桐、曹嘉玥）9月12日，国家主席习近平在印度新德里出席金砖国家领导人第十八次会晤期间会见印度总理莫迪。外交部发言人郭嘉昆14日在例行记者会上表示，习近平主席同莫迪总理已经连续三年成功举行会晤。如果说喀山和天津会晤是引领中印关系“再出发”“再提升”，那么新德里会晤就是两国领导人对中印关系发展的“再确认”。会晤达成的最重要共识就是中印要做伙伴。 郭嘉昆表示，习近平主席指出，中印两国国情不同，完全可以取长补短、相互支持、彼此成就、共同发展。双方要以客观理性的战略认知校准方向，以合作共赢的理…"
