    "description": "新华社东京9月14日电 负责调查日本滨冈核电站地震评估数据造假的第三方委员会14日公布报告指出，在225项被怀疑存在问题的地震震动评估中，至少确认有208项存在虚假说明、隐瞒等不当行为，另外17项因资料不足，无法判断。 综合共同社等日本媒体报道，运营滨冈核电站的中部电力公司14日在名古屋市举行面向媒体的说明会，公开了由公司外部律师等组成的调查委员会撰写的报告。 报告提到，中部电力公司为通过日本原子能规制委员会针对滨冈核电站核电机组重启的…",
    "content": "新华社东京9月14日电 负责调查日本滨冈核电站地震评估数据造假的第三方委员会14日公布报告指出，在225项被怀疑存在问题的地震震动评估中，至少确认有208项存在虚假说明、隐瞒等不当行为，另外17项因资料不足，无法判断。 综合共同社等日本媒体报道，运营滨冈核电站的中部电力公司14日在名古屋市举行面向媒体的说明会，公开了由公司外部律师等组成的调查委员会撰写的报告。 报告提到，中部电力公司为通过日本原子能规制委员会针对滨冈核电站核电机组重启的审查，在确定预期地震最大震动的过程中存在不当行为。预期地震最大震动被视为核电站抗…"
