    "content": "互联网让公益参与更容易，项目颗粒度更细，但也可能弱化公众与公益议题、公益机构、其他行动者之间的联系。技术降低了“做好事”的门槛，但如何将轻量参与转化为长期行动，仍需要更多的探索。 文/黎宇琳 责任编辑：钟金秀 2026年的久久公益节，让“做好事”变得比过去更容易。 用户点开一张虚拟的“心愿折纸”，可以免费送出一个公益心愿，也可以邀请朋友组队完成；在视频号点个赞、去社区参加一次活动、玩一局游戏，甚至买一杯奶茶，都可能触发企业或平台提供的公益金，再由公益机构执行相应项目。 今年久久公益节期间，共有1.37亿用户参与，产…"
