    "content": "记者从中国科技馆获悉，为期5天的2026年全国科普月欢乐科学周活动9月13日在甘肃兰州落幕。全国科技馆联动开展活动近2000场，涵盖科普宣讲、趣味实验秀、原创科普剧等多元形式，奉上了一场科学与文化深度交融的科普盛宴。 此次活动紧扣“欢乐科学 强国同行”主题，立足全国联动、全域普惠的工作思路，汇聚多方力量协同开展科普惠民行动。作为主场的甘肃科技馆累计开展各类科普活动420场，惠及公众4.6万余人次，线上直播观看644.1万人次。 活动期间，中国科技馆联合中国自然科学博物馆学会，汇集全国科普场馆优质资源，累计联动全国各…"
