    "content": "9月14日，演员在推普周开幕式现场进行国家通用语言文字推广普及成果汇报演出。新华社发 新华社长春9月14日电（记者邵美琦、颜麟蕴）9月14日，以“依法推广普及国家通用语言文字，奋进强国建设新征程”为主题的2026年国家通用语言文字推广普及宣传周开幕式在吉林省延边朝鲜族自治州延吉市举行。本届推普周为第29届。 9月14日，演员在推普周开幕式现场进行国家通用语言文字推广普及成果汇报演出。新华社记者 颜麟蕴 摄 统计显示，2025年全国普通话普及率达到87.72%。本届推普周期间，教育部、国家语委举办“语润万家·时代光影…"
