    "author": "吴雨,任军",
    "description": "新华社北京9月14日电（记者吴雨、任军）中国人民银行9月14日发布金融统计数据显示，前8个月我国人民币贷款增加10.44万亿元，其中企（事）业单位贷款增加11.26万亿元。 数据显示，8月末，我国人民币贷款余额282.35万亿元，同比增长4.9%。前8个月，我国住户贷款减少1.03万亿元；企（事）业单位贷款增加11.26万亿元，其中中长期贷款增加5.64万亿元。 在货币供应方面，8月末，我国广义货币（M2）余额356.81万亿元，同比增…",
    "content": "新华社北京9月14日电（记者吴雨、任军）中国人民银行9月14日发布金融统计数据显示，前8个月我国人民币贷款增加10.44万亿元，其中企（事）业单位贷款增加11.26万亿元。 数据显示，8月末，我国人民币贷款余额282.35万亿元，同比增长4.9%。前8个月，我国住户贷款减少1.03万亿元；企（事）业单位贷款增加11.26万亿元，其中中长期贷款增加5.64万亿元。 在货币供应方面，8月末，我国广义货币（M2）余额356.81万亿元，同比增长7.5%；狭义货币（M1）余额115.77万亿元，同比增长4.1%；流通中货币…"
