    "author": "赵瀚泽,曹嘉玥",
    "description": "新华社北京9月14日电（记者曹嘉玥、赵瀚泽）外交部发言人郭嘉昆14日在例行记者会上答问时表示，近日来，也门和红海局势升温，造成无辜平民伤亡和能源等民用设施受损，中方对此深表关切。 当日例行记者会上，有记者问：据媒体报道，也门胡塞组织近日袭击沙特南部4座城市，造成70多名平民受伤，多处设施受损。胡塞组织方面表示其亦受到袭击，造成人员伤亡。中方对此有何评论？ “袭击关乎民生的民用设施不可接受。地区局势动荡加剧不符合各方利益，各国主权安全都应…",
    "content": "新华社北京9月14日电（记者曹嘉玥、赵瀚泽）外交部发言人郭嘉昆14日在例行记者会上答问时表示，近日来，也门和红海局势升温，造成无辜平民伤亡和能源等民用设施受损，中方对此深表关切。 当日例行记者会上，有记者问：据媒体报道，也门胡塞组织近日袭击沙特南部4座城市，造成70多名平民受伤，多处设施受损。胡塞组织方面表示其亦受到袭击，造成人员伤亡。中方对此有何评论？ “袭击关乎民生的民用设施不可接受。地区局势动荡加剧不符合各方利益，各国主权安全都应该得到尊重，通过政治外交途径化解争端是唯一出路。”郭嘉昆表示，中方呼吁相关各方保…"
