    "description": "新华社北京9月14日电（记者梅常伟）国防部长董军14日在北京八一大楼同来访的老挝副总理兼国防部长坎良举行会谈。 董军说，中老命运与共，有着“同志加兄弟”的特殊友好。中国军队愿与老军一道，坚决落实中共中央总书记、国家主席习近平同通伦总书记、国家主席达成的重要共识，进一步密切高层往来，推动各领域务实合作提质增效，为构建新时代全天候中老命运共同体提供坚强支撑，携手维护地区稳定。 坎良说，老方愿同中方加强两军高层沟通和各层级交往，推动各领域务实…",
    "content": "新华社北京9月14日电（记者梅常伟）国防部长董军14日在北京八一大楼同来访的老挝副总理兼国防部长坎良举行会谈。 董军说，中老命运与共，有着“同志加兄弟”的特殊友好。中国军队愿与老军一道，坚决落实中共中央总书记、国家主席习近平同通伦总书记、国家主席达成的重要共识，进一步密切高层往来，推动各领域务实合作提质增效，为构建新时代全天候中老命运共同体提供坚强支撑，携手维护地区稳定。 坎良说，老方愿同中方加强两军高层沟通和各层级交往，推动各领域务实合作取得更多成果。"
