    "content": "今年是中国工农红军长征胜利90周年。9月6日，G3998次复兴号从瑞金始发，途经南昌、武汉、西安，终点抵达延安，沿途经停20多站，运营里程约1800公里。 这条高铁线由7条既有铁路拼接而成。此前，受复杂地形与路网衔接制约，赣南、鄂西、陕北革命老区间高铁通道长期存在短板。2025年底西延高铁通车，延安正式融入全国高铁网；今年西十高铁开通、武西高铁全线贯通，成为拼成这条千里通道最关键的两块工程拼图。 西延高铁洛川站的选址，规划时线路曾面临两难，沿洛河河谷走线，好修又省钱，却方便不了县城群众；抬高线路跨上塬面、在县城设站…"
